class NullCommand : public Command {
public:
  virtual void execute(GameActor&) {}
};

class InputHandler {
public:
  void bind(Button b, Command* c) { bindings_[b] = c; }
  Command* handleInput() {
    for (auto& [button, cmd] : bindings_)
      if (isPressed(button)) return cmd;
    return &nullCommand_;
  }
private:
  std::map<Button, Command*> bindings_;
  NullCommand nullCommand_;
};

class Controller {
public:
  virtual ~Controller() {}
  virtual Command* nextCommand(GameActor& self) = 0;
};

// Game loop
