// (2) undoable: closures capture args + previous state
function makeMoveUnitCommand(unit, x, y) {
  let xBefore, yBefore;
  return {
    execute() {
      xBefore = unit.x; yBefore = unit.y;
      unit.moveTo(x, y);
    },
    undo() { unit.moveTo(xBefore, yBefore); }
  };
}
